// GIVEN — do not change.
public class Copy {
    final int pages;
    final Copy previous;

    Copy(int pages, Copy previous) {
        this.pages = pages;
        this.previous = previous;
    }
}

import java.util.Scanner;

// GIVEN — do not change.
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            Copy last = null;
            for (int i = 1; i <= n; i++) {
                last = new Copy(i % 300 + 1, last);
            }
            System.out.println("chain of " + n + ": length " + Chains.length(last) + ", pages " + Chains.totalPages(last));
        }
    }
}

public class Chains {
    public static int length(Copy c) {
        int n = 0;
        for (Copy x = c; x != null; x = x.previous) {
            n++;
        }
        return n;
    }

    public static long totalPages(Copy c) {
        long sum = 0;
        for (Copy x = c; x != null; x = x.previous) {
            sum += x.pages;
        }
        return sum;
    }
}

